.member-tabs {
  display: flex;
  gap: 28px;
}
.member-tabs a {
  padding: 12px 0;
  color: var(--muted);
  text-decoration: none;
  border-bottom: 3px solid transparent;
}
.member-tabs a[aria-current="page"] {
  color: var(--text);
  border-color: var(--action);
}
.member-total {
  white-space: nowrap;
  overflow-x: auto;
  max-width: 100%;
  margin: 0;
  font-size: clamp(1.8rem, 3.2vw, 2.7rem);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.category-list {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 20px;
}
.category-label {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 10px;
}
.category-label > span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.category-label .amount {
  text-align: right;
}
.signed-bar {
  position: relative;
  height: 9px;
  background: var(--surface);
}
.signed-bar::after {
  content: "";
  position: absolute;
  left: var(--baseline);
  top: -3px;
  bottom: -3px;
  width: 1px;
  background: var(--muted);
  grid-template-columns: minmax(0, 1fr) minmax(0, auto);
  gap: 16px 32px;
}
.member-tabs {
  grid-column: 1 / -1;
}
.member-value {
  min-width: 0;
  text-align: right;
  align-self: center;
  max-width: 420px;
}

.member-value .member-total {
  margin-top: 8px;
  color: var(--accent);
}
.earnings-chart {
  display: block;
  width: 100%;
  overflow: visible;
  margin: 16px 0;
}
.chart-axis {
  fill: var(--muted);
  font-size: 12px;
}
.chart-baseline {
  stroke: var(--line);
}
.earnings-bar {
  fill: var(--accent);
}
.earnings-bar.negative {
  opacity: 0.65;
}
